 'entregables' => 'Aplicación CRUD funcionando|Demostración de la inyección en la versión vulnerable y su bloqueo en la segura|Registro de seis validaciones del servidor',
 'lenguaje' => 'PHP, MySQL', 'dificultad' => 'avanzado', 'sesiones' => 6, 'horas' => 6.0, 'ia' => 1,
