 'entregables' => 'Aplicación accesible desde otro dispositivo|Respaldo restaurado y verificado|Plan de reversión escrito y probado una vez',
 'lenguaje' => 'PHP, MySQL', 'dificultad' => 'avanzado', 'sesiones' => 4, 'horas' => 4.0, 'ia' => 1,
